export type Neighborhood = typeof neighborhoods[number]

export const neighborhoodsByCity = neighborhoods.reduce(
  (acc, n) => {
    if (!acc[n.citySlug]) acc[n.citySlug] = []
    acc[n.citySlug].push(n)
    return acc
  },
  {} as Record<string, Neighborhood[]>
)
